async def act(page):
    """
    From the current "New Rule" form state, open the Actions section, set the rule to
    apply a fixed $10 discount to the whole cart for all customers, and save the rule.

    This function continues from the current page state shown in the accessibility tree.
    """
    import asyncio

    # Small pause to ensure UI stability
    await page.wait_for_timeout(300)

    # Helper to robustly check presence of a locator
    async def present(locator):
        try:
            return (await locator.count()) > 0
        except Exception:
            return False

    # KB functions utility analysis (each function evaluated for this task):
    # - get_dashboard_summary(page): Dashboard snapshot helper. Not useful for editing promo rules.
    # - export_dashboard_snapshot(page,...): Dashboard export helper. Not useful here.
    # - generate_sales_summary_for_date_range(page,...): Dashboard date-range helper. Not useful.
    # - download_revenue_and_orders_report(page,...): Dashboard/reporting helper. Not useful.
    # - export_orders_csv(page,...): Dashboard export helper. Not useful.
    # - export_customers_csv_via_grid(page,...): Grid export helper. Not useful for promo rule editing.
    # None of the KB functions operate on the Shopping Cart Price Rule edit UI, so none are called.

    # 1) Open the Actions section using accessible link/tab/button fallbacks.
    actions_candidates = [
        page.get_by_role("link", name="Actions"),
        page.get_by_role("tab", name="Actions"),
        page.get_by_role("button", name="Actions"),
        page.get_by_role("link").filter(has_text="Actions"),
        page.get_by_role("button").filter(has_text="Actions"),
    ]

    for cand in actions_candidates:
        if await present(cand):
            try:
                await cand.first.click()
                # allow the Actions panel to render
                await page.wait_for_timeout(500)
            except Exception:
                pass
            break

    # 2) Locate the 'Apply' combobox and select a fixed-amount whole-cart option.
    applied = False
    # Try a few likely accessible names for the combobox (with/without required star)
    apply_names = ["Apply", "Apply *", "Apply to", "Apply to *"]
    for name in apply_names:
        apply_cb = page.get_by_role("combobox", name=name)
        if await present(apply_cb):
            # Try common visible labels first
            for label_try in [
                "Fixed amount discount for whole cart",
                "Fixed amount discount",
                "Fixed amount",
                "Fixed amount for whole cart",
            ]:
                try:
                    await apply_cb.first.select_option(label=label_try)
                    applied = True
                    break
                except Exception:
                    pass
            if applied:
                break

            # Inspect available options and pick one that mentions 'fixed' or 'whole'
            opts = apply_cb.get_by_role("option")
            if await present(opts):
                try:
                    texts = await opts.all_inner_texts()
                except Exception:
                    texts = []
                for t in texts:
                    if t and ("fixed" in t.lower() or "whole" in t.lower()):
                        try:
                            await apply_cb.first.select_option(label=t)
                            applied = True
                            break
                        except Exception:
                            pass
            if applied:
                break

            # Value fallback attempts
            for val_try in ["by_fixed", "fixed_amount"]:
                try:
                    await apply_cb.first.select_option(value=val_try)
                    applied = True
                    break
                except Exception:
                    pass
            if applied:
                break

    # If not applied yet, try any combobox on the page and inspect options
    if not applied:
        any_cb = page.get_by_role("combobox")
        if await present(any_cb):
            try:
                total = await any_cb.count()
            except Exception:
                total = 0
            for i in range(total):
                cb = any_cb.nth(i)
                opts = cb.get_by_role("option")
                if not await present(opts):
                    continue
                try:
                    texts = await opts.all_inner_texts()
                except Exception:
                    texts = []
                chosen = None
                for t in texts:
                    if t and ("fixed" in t.lower() or "whole" in t.lower()):
                        chosen = t
                        break
                if chosen:
                    try:
                        await cb.select_option(label=chosen)
                        applied = True
                        break
                    except Exception:
                        pass

    # 3) Set Discount Amount = 10
    discount_locators = [
        page.get_by_label("Discount Amount"),
        page.get_by_label("Discount Amount *"),
    ]
    filled = False
    for dloc in discount_locators:
        if await present(dloc):
            try:
                await dloc.first.click()
                await dloc.first.fill("10")
                filled = True
                break
            except Exception:
                pass

    if not filled:
        # DOM fallback: set known id 'rule_discount_amount' value and dispatch change event
        try:
            await page.evaluate("""
                () => {
                    const el = document.getElementById('rule_discount_amount')
                    if (el) {
                        el.value = '10'
                        el.dispatchEvent(new Event('change', { bubbles: true }))
                        return true
                    }
                    return false
                }
            """)
            filled = True
        except Exception:
            filled = False

    # 4) Save the rule. Use Save as the last action because it navigates away.
    save_candidates = [
        page.get_by_role("button", name="Save"),
        page.get_by_role("button", name="Save Rule"),
        page.get_by_role("button", name="Save and Continue Edit"),
        page.get_by_role("button").filter(has_text="Save"),
    ]

    for s in save_candidates:
        if await present(s):
            try:
                await s.first.click()
                try:
                    await page.wait_for_load_state('networkidle')
                except Exception:
                    # allow some time for server processing if networkidle not reached
                    await page.wait_for_timeout(1200)
            except Exception:
                pass
            break

    return
